(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  function setVal(el, v) {
    const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    setter.call(el, v);
    el.dispatchEvent(new Event('input', {bubbles:true}));
    el.dispatchEvent(new Event('change', {bubbles:true}));
  }
  const pin = Array.from(document.querySelectorAll('input[type=text],input[type=password],input[type=tel],input[type=number]'))
    .find(i => i.offsetParent!==null && (i.maxLength===4 || /pin/i.test(i.id||'')));
  let filled = false;
  if (pin) { setVal(pin, '8751'); filled = true; await sleep(400); }
  const loginBtn = Array.from(document.querySelectorAll('button')).find(b => /^login$/i.test((b.innerText||'').replace(/\s+/g,' ').trim()) && b.offsetParent!==null);
  if (loginBtn) loginBtn.click();
  await sleep(11000);
  return JSON.stringify({
    filled, url: location.href,
    visBtns: Array.from(document.querySelectorAll('button')).filter(b=>b.offsetParent!==null).map(b=>(b.innerText||'').replace(/\s+/g,' ').trim()).filter(Boolean).filter(t=>/login|web|trader|continue|confirm|otp|try/i.test(t)).slice(0,8),
    errs: (Array.from(document.querySelectorAll('div,span,p,label')).map(e=>(e.innerText||'').replace(/\s+/g,' ').trim()).filter(t=>/wrong|invalid|incorrect|failed|mismatch/i.test(t) && t.length<100).slice(0,3)),
    txt: (document.body.innerText||'').replace(/\s+/g,' ').slice(0,300)
  });
})()
